// ============================================================================
// تطبیق‌دهندهٔ دانش‌نامه — امتیازدهی سبک و سریع (بدون وابستگی)
// ============================================================================

/** نرمال‌سازی فارسی: ارقام فارسی/عربی→لاتین، ي/ك عربی→فارسی، حذف اعراب و نیم‌فاصله */
export function normalizeFaText(raw: string): string {
  return String(raw || "")
    .replace(/[۰-۹]/g, (d) => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d)))
    .replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)))
    .replace(/ي/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/[ًٌٍَُِّْـ]/g, "")
    .replace(/[\u200c\u200f\u200e]/g, " ")
    .replace(/[؟?،,؛.!":;()«»\[\]]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

/**
 * تطبیق پیام کاربر با دانش‌نامه — برنده: بیشترین امتیاز (عبارت چندواژه‌ای
 * ۳ امتیاز، واژهٔ ممتاز بلند ۲ امتیاز، واژهٔ کوتاه ۱ امتیاز). حد نصاب ۲.
 */
export function matchKnowledgeFa(rawText: string): KnowledgeEntryFa | null {
  const text = normalizeFaText(rawText);
  if (!text || text.length < 3) return null;
  const words = new Set(text.split(" "));
  let best: KnowledgeEntryFa | null = null;
  let bestScore = 0;
  for (const entry of KNOWLEDGE_FA) {
    let score = 0;
    for (const rawKw of entry.keywords) {
      const kw = normalizeFaText(rawKw);
      if (!kw) continue;
      if (kw.includes(" ")) {
        if (text.includes(kw)) score += 3;
      } else if (kw.length >= 6) {
        if (words.has(kw)) score += 2;
        else if (text.includes(kw)) score += 1; // پسوند/پیوستگی در متن
      } else {
        if (words.has(kw)) score += 1;
      }
      if (score >= 6) break; // بهینه‌سازی — برندهٔ قطعی
    }
    if (score > bestScore) {
      bestScore = score;
      best = entry;
    }
  }
  return bestScore >= 2 ? best : null;
}

/** تعداد مدخل‌های دانش‌نامه — برای گزارش سلامت/UI */
export const KNOWLEDGE_FA_COUNT = KNOWLEDGE_FA.length;
